from bank_rew_s1b import REW as _R2
REW.update(_R2)

def apply(B, key):
    """B = {district: [(q, choices, e), ...]} แก้ตัวเลือกตาม REW[key] พร้อมตรวจว่าตรงข้อ"""
    for d, i, frag, ch in REW.get(key, []):
        q, c, e = B[d][i]
        assert frag in c[0], 'REW %s %s[%d]: ไม่พบ "%s" ในคำตอบเดิม "%s"' % (key, d, i, frag, c[0])
        assert len(ch) == 4 and len(set(ch)) == 4
        B[d][i] = (q, list(ch), e)
    return B
